mapper.update:
update mxk_apps_token_based_details
set algorithmkey = #{et.algorithmKey}, algorithm = #{et.algorithm}, expires = #{et.expires},
    redirecturi = #{et.redirectUri}, cookiename = #{et.cookieName}, tokentype = #{et.tokenType}, instid = #{et.instId}
where id = #{et.id}

mapper.select:
select *
from mxk_apps_token_based_details tbd,
     mxk_apps app
where app.instid = tbd.instid
  and app.id = #{value}
  and tbd.id = #{value}
  and tbd.id = app.id
  and status = 1
